  3078	tribool PackLinuxElf32::canPack()
  3079	{
  3080	    union {
  3081	        unsigned char buf[MAX_ELF_HDR_32];
  3082	        //struct { Elf32_Ehdr ehdr; Elf32_Phdr phdr; } e;
  3083	    } u;
  3084	    COMPILE_TIME_ASSERT(sizeof(u.buf) <= (2*512))
  3085	
  3086	// My earlier design with "extra" Shdrs in output at xct_off
  3087	// DOES NOT WORK because code for EM_ARM has embedded relocations
  3088	// that are not made visible, such as:
  3089	//    ----- glibc-2.31/sysdeps/arm/crti.S
  3090	//            .type call_weak_fn, %function
  3091	//    call_weak_fn:
  3092	//            ldr r3, .LGOT
  3093	//            ldr r2, .LGOT+4
  3094	//    .LPIC:
  3095	//            add r3, pc, r3
  3096	//            ldr r2, [r3, r2]
  3097	//            cmp r2, #0
  3098	//            bxeq lr
  3099	//            b PREINIT_FUNCTION
  3100	//            .p2align 2
  3101	//    .LGOT:
  3102	//            .word _GLOBAL_OFFSET_TABLE_-(.LPIC+8)  // unseen reloc!
  3103	//            .word PREINIT_FUNCTION(GOT)
  3104	//    -----
  3105	// So, PackUnix::PackUnix() disables (but silently accepts) --android-shlib,
  3106	// and see if appending ARM_ATTRIBUTES Shdr is good enough.
  3107	
  3108	    fi->seek(0, SEEK_SET);
  3109	    fi->readx(u.buf, sizeof(u.buf));
  3110	    fi->seek(0, SEEK_SET);
  3111	    Elf32_Ehdr const *const ehdr = (Elf32_Ehdr *) u.buf;
  3112	
  3113	    // now check the ELF header
  3114	    if (checkEhdr(ehdr) != 0)
  3115	        return false;
  3116	
  3117	    // additional requirements for linux/elf386
  3118	    if (get_te16(&ehdr->e_ehsize) != sizeof(*ehdr)) {
  3119	        throwCantPack("invalid Ehdr e_ehsize; try '--force-execve'");
  3120	        return false;
  3121	    }
  3122	    if (e_phoff != sizeof(*ehdr)) {// Phdrs not contiguous with Ehdr
  3123	        throwCantPack("non-contiguous Ehdr/Phdr; try '--force-execve'");
  3124	        return false;
  3125	    }
  3126	
  3127	    if (!canPackOSABI((Elf32_Ehdr *)u.buf)) {
  3128	        return false;
  3129	    }
  3130	    upx_uint32_t max_LOADsz = 0, max_offset = 0;
  3131	    Elf32_Phdr *phdr = phdri;
  3132	    for (unsigned j=0; j < e_phnum; ++phdr, ++j) {
  3133	        if (j > ((MAX_ELF_HDR_32 - sizeof(Elf32_Ehdr)) / sizeof(Elf32_Phdr))) {
  3134	            throwCantPack("too many ElfXX_Phdr; try '--force-execve'");
  3135	            return false;
  3136	        }
  3137	        if (is_LOAD(phdr)) {
  3138	            // The first PT_LOAD must cover the beginning of the file (0==p_offset).
  3139	            upx_uint32_t const p_offset = get_te32(&phdr->p_offset);
  3140	            if (1!= exetype) {
  3141	                exetype = 1;
  3142	                load_va = get_te32(&phdr->p_vaddr);  // class data member
  3143	                upx_uint32_t const off = ~page_mask & (upx_uint32_t)load_va;
  3144	                if (off && off == p_offset) { // specific hint
  3145	                    throwCantPack("Go-language PT_LOAD: try hemfix.c, or try '--force-execve'");
  3146	                    // Fixing it inside upx fails because packExtent() reads original file.
  3147	                    return false;
  3148	                }
  3149	                if (0 != p_offset) { // 1st PT_LOAD must cover Ehdr and Phdr
  3150	                    throwCantPack("first PT_LOAD.p_offset != 0; try '--force-execve'");
  3151	                    return false;
  3152	                }
  3153	                // FIXME: bad for shlib!
  3154	                hatch_off = ~3ul & (3+ get_te32(&phdr->p_memsz));
  3155	            }
  3156	            max_LOADsz = UPX_MAX(max_LOADsz, UPX_MIN(0x200000u, get_te32(&phdr->p_align)));
  3157	            unsigned filesz = get_te32(&phdr->p_filesz);
  3158	            max_LOADsz = UPX_MAX(max_LOADsz, filesz);
  3159	            max_offset = UPX_MAX(max_offset, filesz + p_offset);
  3160	        }
  3161	    }
  3162	    if (canUnpack()) {
  3163	        throwAlreadyPacked();
  3164	    }
