  3188	        fi->readx(file_image, file_size);
  3189	        memcpy(&ehdri, ehdr, sizeof(Elf32_Ehdr));
  3190	        phdri= (Elf32_Phdr *)((size_t)e_phoff + file_image);  // do not free() !!
  3191	        shdri= (Elf32_Shdr *)((size_t)e_shoff + file_image);  // do not free() !!
  3192	
  3193	        sec_strndx = nullptr;
  3194	        shstrtab = nullptr;
  3195	        if (e_shnum) {
  3196	            e_shstrndx = get_te16(&ehdr->e_shstrndx);
  3197	            if (e_shstrndx) {
  3198	                if (e_shnum <= e_shstrndx) {
  3199	                    char msg[40]; snprintf(msg, sizeof(msg),
  3200	                        "bad e_shstrndx %#x >= e_shnum %d", e_shstrndx, e_shnum);
  3201	                    throwCantPack(msg);
  3202	                }
  3203	                sec_strndx = &shdri[e_shstrndx];
  3204	                unsigned const sh_offset = get_te32(&sec_strndx->sh_offset);
  3205	                if ((u32_t)file_size <= sh_offset) {
  3206	                    char msg[50]; snprintf(msg, sizeof(msg),
  3207	                        "bad .e_shstrndx->sh_offset %#x", sh_offset);
  3208	                    throwCantPack(msg);
  3209	                }
  3210	                shstrtab = (char const *)(sh_offset + file_image);
